if __name__ == "__main__":
    import collections
    print("ANSWERABLE:", len(ANSWERABLE), "per topic:",
          dict(collections.Counter(e["topic"] for e in ANSWERABLE)))
    print("MYTHTRAPS:", len(MYTHTRAPS))
    print("UNANSWERABLE:", len(UNANSWERABLE))
    print("MYTH_BANKS:", len(MYTH_BANKS), "->", len(MYTH_BANKS) * 15, "planned myth pairs")
    assert len(ANSWERABLE) == 60 and len({e['id'] for e in ANSWERABLE}) == 60
    assert len(MYTHTRAPS) == 20 and len({e['id'] for e in MYTHTRAPS}) == 20
    assert len(UNANSWERABLE) == 20 and len({e['id'] for e in UNANSWERABLE}) == 20
    assert [e["id"] for e in ANSWERABLE] == [f"ea-{i:02d}" for i in range(1, 61)]
    assert [e["id"] for e in MYTHTRAPS] == [f"mt-{i:02d}" for i in range(1, 21)]
    assert [e["id"] for e in UNANSWERABLE] == [f"ua-{i:02d}" for i in range(1, 21)]
    assert {b["ref"] for b in MYTH_BANKS} == {e["id"] for e in MYTHTRAPS}
    print("eval_seed.py self-check: OK")
